-- Ne remplace jamais un contenu déjà administré. Les guides en wolof
-- sont publiés après validation du texte et de l'enregistrement.
INSERT INTO system_configs (key,value) VALUES ('help.guides', '[{"id": "envoi", "language": "fr", "title": "Envoyer un colis", "text": "Renseignez le destinataire et le trajet. Décrivez le colis et son poids. Choisissez un chauffeur ou publiez en libre service. Relisez les informations et le prix avant de publier.", "audioUrl": "/api/v1/public/help-audio/envoi.mp3", "published": true}, {"id": "livraison", "language": "fr", "title": "Recevoir un colis", "text": "Consultez la dernière mise à jour du suivi. Une ancienne position ne montre pas le véhicule en direct. Communiquez le code de livraison uniquement lorsque le colis est remis au destinataire.", "audioUrl": "/api/v1/public/help-audio/livraison.mp3", "published": true}, {"id": "chauffeur", "language": "fr", "title": "Effectuer une livraison", "text": "Vérifiez le trajet et le prix avant d’accepter. Mettez à jour la mission à chaque étape. Confirmez la remise avec le code du destinataire, puis consultez les encaissements et la commission.", "audioUrl": "/api/v1/public/help-audio/chauffeur.mp3", "published": true}]'::jsonb) ON CONFLICT (key) DO NOTHING;
